const images=['assets/italian-garden.jpg','assets/meadow.jpg','assets/courtyard.jpg'];
let lang='pl',current=0,paused=matchMedia('(prefers-reduced-motion: reduce)').matches;
const track=document.querySelector('#carousel-track'),region=document.querySelector('.carousel'),dialog=document.querySelector('#contact-dialog');
let manualHold=0,pointerInside=false,carouselVisible=false;
const t=key=>copy[lang][key];
function renderCarousel(animate=false){
const mobile=matchMedia('(max-width:600px)').matches;
const order=mobile?[current,(current+1)%3,(current+2)%3]:[(current+2)%3,current,(current+1)%3];
track.innerHTML=order.map(index=>`<figure class="project ${index===current?'active':''} ${animate?'entering':''}" data-index="${index}" role="group" aria-roledescription="slide" aria-label="${index+1} / 3 — ${t('cities')[index]}"><div class="project-image"><img src="${images[index]}" alt="${t('alts')[index]}" width="1536" height="1024" loading="lazy"><span class="roman">${['I','II','III'][index]}</span></div><figcaption><h3>${t('cities')[index]}</h3><p>${t('descriptions')[index]}</p></figcaption></figure>`).join('');track.scrollLeft=0;document.querySelector('#current-slide').textContent=String(current+1).padStart(2,'0');}
function updatePause(){const b=document.querySelector('#pause');b.setAttribute('aria-pressed',String(paused));b.querySelector('[data-i18n]').textContent=t(paused?'play':'pause');b.querySelector('.pause-icon').textContent=paused?'▷':'Ⅱ';}
function setLanguage(next,persist=true){lang=next in copy?next:'pl';document.documentElement.lang=lang;document.title=t('title');document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=t(el.dataset.i18n));document.querySelectorAll('[data-alt]').forEach(el=>el.alt=t(el.dataset.alt));document.querySelectorAll('[data-lang]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.lang===lang)));document.querySelector('#previous').ariaLabel=t('previous');document.querySelector('#next').ariaLabel=t('next');region.ariaLabel=t('carousel');dialog.querySelector('.close').ariaLabel=t('close');document.querySelector('.status').textContent='';renderCarousel();updatePause();if(persist)try{localStorage.setItem('terren-language',lang)}catch{}}
function move(direction){current=(current+direction+3)%3;renderCarousel(true);manualHold=Date.now()+10000;}
document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>setLanguage(b.dataset.lang)));
document.querySelector('#previous').addEventListener('click',()=>move(-1));document.querySelector('#next').addEventListener('click',()=>move(1));document.querySelector('#pause').addEventListener('click',()=>{paused=!paused;updatePause()});
region.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();move(e.key==='ArrowRight'?1:-1)}});region.addEventListener('mouseenter',()=>pointerInside=true);region.addEventListener('mouseleave',()=>pointerInside=false);track.addEventListener('pointerdown',()=>manualHold=Date.now()+12000);
new IntersectionObserver(entries=>carouselVisible=entries[0].isIntersecting,{threshold:.3}).observe(region);
let swipeTimer;
track.addEventListener('scroll',()=>{if(!matchMedia('(max-width:600px)').matches)return;clearTimeout(swipeTimer);swipeTimer=setTimeout(()=>{const center=track.getBoundingClientRect().left+track.clientWidth/2;const closest=[...track.children].sort((a,b)=>{const ar=a.getBoundingClientRect(),br=b.getBoundingClientRect();return Math.abs(ar.left+ar.width/2-center)-Math.abs(br.left+br.width/2-center)})[0];if(closest){current=Number(closest.dataset.index);document.querySelector('#current-slide').textContent=String(current+1).padStart(2,'0')}},150)});
setInterval(()=>{if(!paused&&!dialog.open&&!pointerInside&&carouselVisible&&!document.hidden&&!region.contains(document.activeElement)&&Date.now()>manualHold){current=(current+1)%3;renderCarousel(true)}},6500);
matchMedia('(max-width:600px)').addEventListener('change',()=>renderCarousel());
document.querySelector('#contact-button').addEventListener('click',()=>{dialog.showModal();document.body.style.overflow='hidden'});dialog.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>document.body.style.overflow='');dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()});
document.querySelector('#brief-form').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.currentTarget);const text=`TERREN\n\n${t('place')}: ${d.get('place')}\n${t('area')}: ${d.get('area')||'—'}\n\n${t('dream')}:\n${d.get('dream')}\n`;const url=URL.createObjectURL(new Blob(['\uFEFF',text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`TERREN-brief-${lang}.txt`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('.status').textContent=t('saved')});
try{setLanguage(localStorage.getItem('terren-language')||'pl',false)}catch{setLanguage('pl',false)}document.querySelector('#year').textContent=new Date().getFullYear();
